def transform(grid):
 h,w=len(grid),len(grid[0]); seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c] in (0,2) or (r,c) in seen: continue
   col=grid[r][c]; cells={(r,c)}; seen.add((r,c)); q=[(r,c)]
   for x,y in q:
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
      seen.add((a,b)); cells.add((a,b)); q.append((a,b))
   t=min(x for x,y in cells); bot=max(x for x,y in cells); l=min(y for x,y in cells); rr=max(y for x,y in cells)
   if not any(grid[x][y]==2 for x in range(t,bot+1) for y in range(l,rr+1)):
    objs.append((cells,bot,l,rr))
 out=[[0]*w for _ in range(h)]; kept=set(); change=True
 while change:
  change=False
  for i,(cells,b,l,r) in enumerate(objs):
   if i not in kept and (b==h-1 or any(out[b+1][c]!=0 for c in range(l,r+1))):
    kept.add(i); change=True
    for x,y in cells: out[x][y]=grid[x][y]
 return out

